<template>
  <view class="page" :style="responsiveStyle">
    <view class="header"><view class="back" @tap="goBack"><image src="/static/orders/traveling-back.svg" mode="aspectFit" /></view><text class="header-title">會員里程</text></view>
    <scroll-view class="content" scroll-y>
      <view class="hero-panel">
        <view class="hero-orbit orbit-one"/><view class="hero-orbit orbit-two"/>
        <view class="hero-heading"><view><text class="eyebrow">MEMBER MILEAGE</text><text class="hero-label">可用里程</text></view><view class="member-badge">SILVER · 會員</view></view>
        <view class="hero-balance"><text class="balance">{{balance.toLocaleString()}}</text><text class="unit">KM</text></view>
        <view class="hero-footer"><view><text>即將到期</text><strong>{{expiringAmount}} KM</strong><text>{{expiringAt ? expiringAt.slice(0, 10).replaceAll('-', '/') : '暫無到期里程'}}</text></view><view class="hero-link" @tap="showHistory">查看明細 <text>↗</text></view></view>
      </view>
      <view class="quick-actions"><view v-for="action in actions" :key="action.title" class="quick-item" @tap="quickAction(action.title)"><view :class="['quick-icon',action.tone]">{{action.icon}}</view><view><text>{{action.title}}</text><text class="quick-desc">{{action.desc}}</text></view><text class="quick-arrow">›</text></view></view>
      <view class="section progress-section"><view class="section-head"><view><text class="section-kicker">YOUR STATUS</text><text class="section-title">會員成長進度</text></view><text class="progress-level">SILVER</text></view><view class="progress-copy"><text>距離 GOLD 會員還有</text><strong>{{Math.max(0, 3000 - balance).toLocaleString()}} KM</strong></view><view class="level-progress"><view class="level-value" :style="{width:`${Math.min(100, balance / 30)}%`}"/></view><view class="level-scale"><text>1,000 KM</text><text>3,000 KM</text></view></view>
      <view class="section activity-section"><view class="section-head"><view><text class="section-kicker">ACTIVITY</text><text class="section-title">里程概覽</text></view><text class="section-more" @tap="showHistory">查看全部 ›</text></view><view class="metric-grid"><view><text>本月累積</text><strong>+ {{monthlyEarned}}</strong><small>KM</small></view><view><text>年度累積</text><strong>+ {{yearlyEarned}}</strong><small>KM</small></view><view><text>累計獲得</text><strong>+ {{balance}}</strong><small>KM</small></view></view><view v-if="bars.length" class="trip-chart"><view v-for="bar in bars" :key="bar.month" class="chart-item"><text>{{bar.value}}</text><view class="bar-track"><view class="bar-value" :style="{height:`${bar.height}px`}"/></view><text>{{bar.month}}</text></view></view><view v-else class="empty-chart">完成行程後，這裡會顯示里程累積</view></view>
      <view class="section rewards"><view class="section-head"><view><text class="section-kicker">MEMBER PERKS</text><text class="section-title">里程兌換</text><text class="section-note">把里程變成下一程的專屬禮遇</text></view><text class="reward-wallet">{{balance.toLocaleString()}} KM</text></view><scroll-view class="reward-scroll" scroll-x :show-scrollbar="false"><view v-if="rewards.length" class="reward-row"><view v-for="reward in rewards" :key="reward.id" class="reward-card"><view class="reward-visual blue"><text>R</text><view class="reward-tag">MEMBER ONLY</view></view><view class="reward-card-copy"><text class="reward-title">{{reward.name}}</text><text class="reward-desc">{{reward.description}}</text><view class="redeem-row"><view><strong>{{reward.cost.toLocaleString()}} <small>KM</small></strong><text class="reward-balance">兌換後享用專屬優惠</text></view><view :class="['redeem',{disabled:balance<reward.cost}]" @tap="redeem(reward)">{{balance<reward.cost?'不足':'兌換'}}</view></view></view></view></view><view v-else class="empty-rewards">暫無可兌換禮遇</view></scroll-view></view>
      <view class="section history"><view class="section-head"><view><text class="section-kicker">RECENT ACTIVITY</text><text class="section-title">里程明細</text></view><text class="filter">最近 30 天⌄</text></view><view v-if="history.length"><view v-for="item in history" :key="item.id" class="history-row"><view :class="['history-icon',item.amount>0?'earn':'spend']">{{item.amount>0?'＋':'－'}}</view><view class="history-copy"><text>{{item.reason}}</text><text>{{item.createdAt.slice(0, 16).replace('T', ' ')}}</text></view><text :class="['history-amount',{negative:item.amount<0}]">{{item.amount>0?'+ ':''}}{{item.amount}} <small>KM</small></text></view></view><view v-else class="empty-history">目前還沒有里程紀錄</view></view>
      <view class="section rules-section"><view class="section-head"><view><text class="section-kicker">HOW IT WORKS</text><text class="section-title">會員里程規則</text></view><text class="rules-tag">使用須知</text></view><view class="rule-row"><text class="rule-number">01</text><view><text class="rule-title">完成行程，自動累積</text><text class="rule-copy">完成合資格跨境接送或機場接送行程後，里程將自動存入會員帳戶。</text></view></view><view class="rule-row"><text class="rule-number">02</text><view><text class="rule-title">里程有效 12 個月</text><text class="rule-copy">系統將優先使用最早到期的里程，避免權益閒置。</text></view></view><view class="rule-row"><text class="rule-number">03</text><view><text class="rule-title">兌換專屬乘車禮遇</text><text class="rule-copy">里程不可轉讓、兌換現金或與部分優惠同時使用。</text></view></view></view>
      <view class="tip">里程規則及兌換內容以預約確認頁顯示為準</view><view class="bottom-space"/>
    </scroll-view>
  </view>
</template>
<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useResponsiveCanvas } from '../../composables/useResponsiveCanvas'
import { closeCachedPage } from '../../utils/navigation'
import { getMileageSummary, redeemMileageReward, type MileageReward, type MileageLedger } from '../../services/api'

const { responsiveStyle } = useResponsiveCanvas()
const balance = ref(0)
const monthlyEarned = ref(0)
const yearlyEarned = ref(0)
const expiringAmount = ref(0)
const expiringAt = ref<string | null>(null)
const rewards = ref<MileageReward[]>([])
const history = ref<MileageLedger[]>([])
const message = ref('')
const loading = ref(true)
const bars = computed(() => history.value.filter(item => item.amount > 0).slice(0, 5).reverse().map((item, index) => ({ month: item.createdAt.slice(5, 7) + '月', value: item.amount, height: Math.max(18, Math.min(64, item.amount / 8 + index * 3)) })))
const actions=[{icon:'程',title:'里程明細',desc:'查看收支',tone:'blue'},{icon:'賺',title:'賺取里程',desc:'完成任務',tone:'green'},{icon:'換',title:'兌換專區',desc:'會員禮遇',tone:'gold'}]
const load = async () => { loading.value = true; try { const data = await getMileageSummary(); balance.value = data.balance; monthlyEarned.value = data.monthlyEarned; yearlyEarned.value = data.yearlyEarned; expiringAmount.value = data.expiringAmount; expiringAt.value = data.expiringAt; rewards.value = data.rewards; history.value = data.ledger } catch (error) { message.value = error instanceof Error ? error.message : '會員里程暫時無法載入' } finally { loading.value = false } }
const goBack=()=>closeCachedPage('/pages/trips/trips')
const showHistory=()=>uni.showToast({title:history.value.length ? '已顯示最近 20 筆明細' : '暫無里程明細',icon:'none'})
const quickAction=(name:string)=> name === '里程明細' ? showHistory() : uni.showToast({title:`${name}功能將於符合資格後開放`,icon:'none'})
const redeem=async (reward: MileageReward) => { if (balance.value < reward.cost) { uni.showToast({title:'可用里程不足',icon:'none'}); return }; try { const result = await redeemMileageReward(reward.id); uni.showToast({title:result.message,icon:'success'}); await load() } catch (error) { uni.showToast({title:error instanceof Error ? error.message : '里程兌換失敗',icon:'none'}) } }
onMounted(load)
</script>
<style scoped>
