x;width:max-content;padding-right:18px}.reward-card{width:190px;height:218px;overflow:hidden;border:1px solid #e5eaf0;border-radius:17px;background:#fff}.reward-visual{position:relative;height:92px;display:flex;align-items:center;justify-content:center;font-size:24px;font-weight:700}.reward-visual.blue{background:linear-gradient(135deg,#dff2ed,#b5ded5);color:#187f69}.reward-tag{position:absolute;left:9px;top:9px;padding:4px 7px;border-radius:8px;background:rgba(255,255,255,.82);font-size:7px;color:#52716b}.reward-card-copy{padding:0 11px}.reward-title{display:block;margin-top:10px;font-size:11px;font-weight:700;color:#263746}.reward-desc{display:block;margin-top:4px;font-size:8px;color:#969ca5;line-height:1.4}.redeem-row{margin-top:10px;display:flex;align-items:center;justify-content:space-between}.redeem-row>view:first-child{display:flex;flex-direction:column;gap:3px}.redeem-row strong{font-size:11px;color:#285cfc}.reward-balance{font-size:7px;color:#a0a7b0;white-space:nowrap}.redeem{width:50px;height:26px;border-radius:13px;display:flex;align-items:center;justify-content:center;background:#285cfc;color:#fff;font-size:9px;font-weight:600}.redeem.disabled{background:#c8cdd5}.empty-rewards{height:190px;width:396px;background:#fafbfc;border-radius:12px}.history{padding-bottom:6px}.history-row{height:61px;display:flex;align-items:center;border-bottom:1px solid #edf0f3}.history-icon{width:32px;height:32px;border-radius:10px;display:flex;align-items:center;justify-content:center;font-size:15px}.history-icon.earn{background:#e2faf1;color:#11a46d}.history-icon.spend{background:#fff0ed;color:#ed6e5c}.history-copy{margin-left:11px;display:flex;flex-direction:column;gap:4px}.history-copy text:first-child{font-size:10px;font-weight:600}.history-copy text:last-child{font-size:8px;color:#999fa8}.history-amount{margin-left:auto;font-size:11px;font-weight:700;color:#12a56e}.history-amount.negative{color:#eb6a58}.empty-history{height:64px}.rules-section{margin-top:12px;padding:17px 19px 8px}.rules-tag{padding:4px 8px;border-radius:10px;background:#e9efff;color:#285cfc;font-size:9px}.rule-row{display:flex;gap:12px;padding:14px 0;border-bottom:1px solid #edf0f3}.rule-row:last-child{border-bottom:0}.rule-number{font-size:11px;font-weight:700;color:#285cfc}.rule-row view{flex:1}.rule-title{display:block;font-size:11px;font-weight:700}.rule-copy{display:block;margin-top:4px;font-size:9px;line-height:1.5;color:#8b929c}.tip{padding:16px 25px;text-align:center;font-size:8px;color:#979da6}.bottom-space{height:30px}

